INSERT INTO `alumni_testimonials` VALUES (1,'Rian Pratama',NULL,'Caregiver (Kaigo)','Tokyo, Jepang','Alhamdulillah berkat bimbingan intensif Sensei di LPK Masayume, saya lulus N4 dalam 4 bulan dan langsung lolos wawancara user di Tokyo. Gaji dan fasilitas sesuai janji!','Tokutei Ginou',1,1,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(2,'Siti Nurhaliza',NULL,'Pengolahan Makanan (Food Processing)','Osaka, Jepang','LMS dan CBT Masayume sangat membantu latihan listening dan furigana. Begitu sampai di Osaka, tidak kaget dengan komunikasi bahasa Jepang sehari-hari.','Tokutei Ginou',2,1,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(3,'Budi Santoso',NULL,'Manufaktur Komponen Mesin','Aichi, Jepang','Proses pengurusan COE dan Visa sangat transparan dan dibantu penuh sampai bandara Narita. Terima kasih LPK Masayume!','Magang 3 Tahun',3,1,'2026-10-21 06:18:06','2026-10-21 06:18:06');
