:12:\"LPK Masayume\";s:11:\"lpk_tagline\";s:52:\"Wujudkan Karir Impian ke Jepang Bersama LPK Masayume\";s:14:\"lpk_legal_info\";s:42:\"Izin Resmi Kemenaker RI & Terakreditasi SO\";s:19:\"lpk_topbar_subtitle\";s:49:\"Program Tokutei Ginou (SSW) & Magang Kerja Jepang\";s:14:\"lpk_hero_badge\";s:49:\"LEMBAGA PELATIHAN KERJA JEPANG RESMI & TERPERCAYA\";s:20:\"lpk_hero_description\";s:200:\"Membuka jalan karir profesional di Jepang melalui Program Tokutei Ginou (SSW) dan Magang Kerja. Didukung kurikulum terpadu JLPT N4, pelatih Sensei berpengalaman, dan sistem ujian CBT Digital mutakhir.\";s:15:\"reg_status_open\";i:1;s:15:\"reg_batch_title\";s:23:\"Gelombang Angkatan Baru\";s:17:\"reg_card_subtitle\";s:38:\"Target Kelulusan N4 & Penempatan Kerja\";s:17:\"reg_point_1_title\";s:25:\"Target Kelulusan Terjamin\";s:16:\"reg_point_1_desc\";s:68:\"Sertifikasi JLPT N4 & JFT-Basic A2 dalam waktu 4-6 bulan pembekalan.\";s:17:\"reg_point_2_title\";s:23:\"Bebas Biaya Tak Terduga\";s:16:\"reg_point_2_desc\";s:74:\"Transparan 100% rincian biaya pelatihan, paspor, MCU hingga tiket pesawat.\";s:17:\"reg_point_3_title\";s:22:\"Penempatan Kerja Pasti\";s:16:\"reg_point_3_desc\";s:80:\"Kerjasama resmi dengan puluhan Asosiasi Kumiai dan Perusahaan di seluruh Jepang.\";s:17:\"stat_passing_rate\";i:98;s:18:\"stat_passing_label\";s:26:\"Tingkat Kelulusan Ujian N4\";s:17:\"stat_alumni_count\";s:4:\"350+\";s:17:\"stat_alumni_label\";s:25:\"Siswa Berangkat ke Jepang\";s:18:\"stat_partner_count\";s:3:\"85+\";s:18:\"stat_partner_label\";s:23:\"Mitra Perusahaan Jepang\";s:16:\"stat_legal_count\";s:4:\"100%\";s:16:\"stat_legal_label\";s:20:\"Izin Resmi Kemenaker\";s:11:\"about_title\";s:81:\"Mencetak Tenaga Kerja Profesional Berkarakter & Berkualitas untuk Industri Jepang\";s:8:\"about_p1\";s:199:\"LPK Masayume (株式会社 正夢) adalah Lembaga Pelatihan Kerja terkemuka yang berfokus pada pembekalan bahasa, budaya, kedisiplinan (Hensachi & Aisatsu), serta keterampilan teknis kerja di Jepang.\";s:8:\"about_p2\";s:229:\"Kami menggabungkan metode pembelajaran tradisional yang intensif dengan platform digital modern (LMS & CBT Standar Jepang) sehingga seluruh siswa dipantau progres kemampuan bahasanya secara presisi dari nol hingga siap berangkat.\";s:21:\"about_feature_1_title\";s:18:\"Sensei Native & N2\";s:20:\"about_feature_1_desc\";s:72:\"Pengajar berpengalaman lulusan universitas Jepang & bersertifikat resmi.\";s:21:\"about_feature_2_title\";s:18:\"Asrama & Fasilitas\";s:20:\"about_feature_2_desc\";s:73:\"Lingkungan belajar kondusif dengan laboratorium bahasa & lab CBT mandiri.\";s:16:\"philosophy_title\";s:29:\"Mimpi Nyata Menuju Masa Depan\";s:15:\"philosophy_desc\";s:206:\"Dalam bahasa Jepang, 正夢 (Masayume) berarti \"Mimpi yang Menjadi Kenyataan\". Kami berkomitmen mendampingi setiap siswa agar mimpi bekerja dan sukses di Jepang terwujud secara aman, legal, dan bermartabat.\";s:13:\"contact_phone\";s:14:\"0812-3456-7890\";s:16:\"contact_whatsapp\";i:6281234567890;s:13:\"contact_email\";s:23:\"info@masayume-lpk.co.id\";s:15:\"contact_address\";s:77:\"Gedung LPK Masayume, Jl. Pelatihan Karir Jepang No. 88, Jawa Barat, Indonesia\";s:13:\"contact_hours\";s:32:\"Senin - Sabtu: 08.00 - 17.00 WIB\";s:16:\"contact_maps_url\";s:23:\"https://maps.google.com\";s:16:\"social_instagram\";s:21:\"https://instagram.com\";s:15:\"social_facebook\";s:20:\"https://facebook.com\";s:13:\"social_tiktok\";s:18:\"https://tiktok.com\";s:14:\"social_youtube\";s:19:\"https://youtube.com\";s:16:\"footer_copyright\";s:66:\"© 2026 LPK Masayume (正夢). Hak Cipta Dilindungi Undang-Undang.\";}',1792563787),('lms_cache_today_vocabularies_sample','O:39:\"Illuminate\\Database\\Eloquent\\Collection\":2:{s:8:\"\0*\0items\";a:40:{i:0;O:21:\"App\\Models\\Vocabulary\":33:{s:13:\"\0*\0connection\";s:5:\"mysql\";s:8:\"\0*\0table\";s:12:\"vocabularies\";s:13:\"\0*\0primaryKey\";s:2:\"id\";s:10:\"\0*\0keyType\";s:3:\"int\";s:12:\"incrementing\";b:1;s:7:\"\0*\0with\";a:0:{}s:12:\"\0*\0withCount\";a:0:{}s:19:\"pr