/*!40000 ALTER TABLE `chapters` DISABLE KEYS */;
INSERT INTO `chapters` VALUES (1,1,26,'第26課 (Bab 26): Bentuk ~んです (~ndesu) & Permintaan Tolong','Memahami penggunaan ungkapan penjelas alasan dan meminta bantuan secara sopan.',26,1,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(2,1,1,'第1課 (Bab 1): Perkenalan Diri & Pola Kalimat Dasar (~ wa ~ desu)','Pola Dasar:\n1. N1 は N2 です (N1 adalah N2)\n2. N1 は N2 じゃありません / ではありません (N1 bukan N2)\n3. N1 は N2 ですか (Apakah N1 adalah N2?)\n4. N も (Juga)\n5. N1 の N2 (Kepemilikan / Asal)',1,1,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(3,1,2,'第2課 (Bab 2): Kata Tunjuk Benda (これ, それ, あれ, この, その, あの)','Pola Dasar:\n1. これ / それ / あれ は N です\n2. この / その / あの N は ... です\n3. そうです / そうじゃありません\n4. ~ か ~ か (Pilihan)',2,1,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(4,1,3,'第3課 (Bab 3): Kata Tunjuk Tempat (ここ, そこ, あそこ, どこ)','Pola Dasar:\n1. ここ / そこ / あそこ は N (tempat) です\n2. N は N (tempat) です\n3. どこ / どちら (Tanya Tempat / Arah Sopan)\n4. N1 の N2 (Asal Negara / Perusahaan Produk)',3,1,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(5,1,4,'第4課 (Bab 4): Waktu, Jam, Menit, dan Kata Kerja Rutinitas (起きる, 寝る)','Pola Dasar:\n1. 今 ~ 時 ~ 分 です (Sekarang jam ~ lewat ~ menit)\n2. V-ます / V-ません / V-ました / V-ませんでした\n3. N (waktu) に V (Pada jam ... melakukan ...)\n4. N1 から N2 まで (Dari ... sampai ...)\n5. N1 と N2 (Dan)',4,1,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(6,1,5,'第5課 (Bab 5): Perpindahan & Transportasi (行く, 来る, 帰る)','Pola Dasar:\n1. N (tempat) へ 行きます / 来ます / 帰ります\n2. どこ [へ] も 行きません (Tidak pergi ke mana pun)\n3. N (kendaraan) で 行きます (Pergi dengan kendaraan)\n4. N (orang) と 行きます (Pergi bersama orang)\n5. いつ (Kapan)',5,1,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(7,1,6,'第6課 (Bab 6): Aktivitas Objek & Tempat Tindakan (食べる, 飲む, ~を, ~で)','Pola Dasar:\n1. N を V (transitif) (Melakukan aksi terhadap objek)\n2. 何 を しますか (Melakukan apa?)\n3. N (tempat) で V (Melakukan aksi di suatu tempat)\n4. V-ませんか (Maukah bersama-sama? / Mengajak)\n5. V-ましょう (Mari kita lakukan!)',6,1,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(8,1,7,'第7課 (Bab 7): Alat, Bahasa, Memberi & Menerima (あげる, もらう, もう~ました)','Pola Dasar:\n1. N (alat/sarana) で V (Melakukan dengan alat / bahasa tertentu)\n2. \'Kata/Kalimat\' は ~語で 何ですか (Apa artinya dalam bahasa...?)\n3. N (orang) に あげます / もらいます (Memberi / Menerima)\n4. もう V-ました (Sudah selesai melakukan)\n5. まだです (Belum)',7,1,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(9,1,8,'第8課 (Bab 8): Kata Sifat I dan Kata Sifat Na (形容詞 Keiyoushi)','Pola Dasar:\n1. N は い-Adj です / な-Adj です\n2. Negatif: ~くないです (I-Adj) / ~じゃありません (Na-Adj)\n3. N1 は どんな N2 ですか (N1 itu N2 yang bagaimana?)\n4. そして (Dan) vs が (Tetapi)',8,1,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(10,1,9,'第9課 (Bab 9): Kesukaan, Kemahiran, Kepemilikan & Alasan (~が 好き, ~が わかる, ~から)','Pola Dasar:\n1. N が 好きです / 嫌いです (Suka / Benci)\n2. N が 上手です / 下手です (Mahir / Kurang mahir)\n3. N が わかります / あります (Mengerti / Memiliki benda mati)\n4. Kata Keterangan: よく, だいたい, たくさん, すこし, ぜんぜん\n5. S1 から、S2 (Karena S1, maka S2)',9,1,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(11,1,10,'第10課 (Bab 10): Keberadaan Makhluk Hidup & Benda (います, あります, Posisi Lokasi)','Pola Dasar:\n1. N (tempat) に N が あります (Ada benda mati di tempat...)\n2. N (tempat) に N が います (Ada orang/hewan di tempat...)\n3. N は N (tempat) に あります / います\n4. Kosakata Posisi: 上 (atas), 下 (bawah), 前 (depan), 後ろ (belakang), 隣 (sebelah), 中 (dalam)\n5. N1 や N2 など (N1 dan N2, dan lain-lain)',10,1,'2026-10-21 06:18:06','2026-10-21 06:18:06');
/*!40000 ALTER TABLE `chapters` ENABLE KEYS */;
UNLOCK TABLES;

