INSERT INTO `language_levels` VALUES (1,'N5','JLPT N5 (Tingkat Dasar)','JLPT N5 (入門・基礎)','Tingkat dasar pemahaman huruf hiragana, katakana, kanji dasar, dan percakapan harian.',1,1,'2026-10-21 06:18:05','2026-10-21 06:18:05'),(2,'N4','JLPT N4 & JFT-Basic A2 (Standar Kerja)','JLPT N4 / JFT A2 (就労基準)','Standar minimum kemampuan bahasa Jepang untuk bekerja dan magang di Jepang.',2,1,'2026-10-21 06:18:05','2026-10-21 06:18:05'),(3,'N3','JLPT N3 (Tingkat Menengah)','JLPT N3 (中級実用)','Pemahaman komunikasi situasi kerja spesifik dan kehidupan sehari-hari mandiri.',3,1,'2026-10-21 06:18:05','2026-10-21 06:18:05'),(4,'N2','JLPT N2 (Tingkat Mahir / Karir)','JLPT N2 (上級・ビジネス)','Kemampuan membaca artikel surat kabar dan komunikasi bisnis tingkat lanjut.',4,1,'2026-10-21 06:18:05','2026-10-21 06:18:05'),(5,'N1','JLPT N1 (Tingkat Fasih / Native)','JLPT N1 (最上級・ネイティブ)','Kemampuan bahasa Jepang kompleks dan berbobot secara fasih setara native speaker.',5,1,'2026-10-21 06:18:05','2026-10-21 06:18:05'),(6,'JFT_A2','JFT-Basic A2 (SSW / Tokutei Ginou)','JFT-Basic A2 (特定技能)','Standar uji kompetensi komunikasi kerja untuk visa Tokutei Ginou pekerja berketerampilan spesifik.',6,1,'2026-10-21 06:18:05','2026-10-21 06:18:05');
