/*!40000 ALTER TABLE `lessons` DISABLE KEYS */;
INSERT INTO `lessons` VALUES (1,1,'Pola Tata Bahasa: ~んです / ~んですが','text_grammar','<p class=\"text-base text-slate-700 leading-relaxed mb-4\">Pola <strong>〜んです (~ndesu)</strong> digunakan saat pembicara ingin memberikan alasan, latar belakang keadaan, atau meminta penjelasan yang lebih mendalam dari lawan bicara.</p>\n                <div class=\"bg-amber-50 border-l-4 border-amber-500 p-4 rounded-r-xl my-4\">\n                    <p class=\"font-bold text-amber-900\">Rumus Pembentukan:</p>\n                    <p class=\"text-amber-800\">Bentuk Biasa (Futsuukei) + んです</p>\n                    <p class=\"text-sm text-amber-700 mt-1\">*Untuk Kata Benda (N) & Kata Sifat-Na (Na-Adj) bentuk sekarang positif: ditambah な (contoh: 暇なんです / 休みなんです)</p>\n                </div>\n                <h4 class=\"font-bold text-slate-800 text-lg mt-6 mb-2\">Contoh Kalimat (例文):</h4>\n                <ul class=\"space-y-3\">\n                    <li class=\"bg-white p-3 rounded-lg border border-slate-200\">\n                        <span class=\"text-japan-red font-semibold\">A: </span>どうして <ruby>遅<rt>おく</rt></ruby>れたんですか。<br>\n                        <span class=\"text-japan-slate text-sm\">Kenapa Anda terlambat?</span><br>\n                        <span class=\"text-japan-red font-semibold\">B: </span>バスが <ruby>来<rt>こ</rt></ruby>なかったんです。<br>\n                        <span class=\"text-japan-slate text-sm\">Karena busnya tidak datang.</span>\n                    </li>\n                </ul>',NULL,NULL,NULL,NULL,15,1,1,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(2,2,'Tata Bahasa Bab 1: Partikel は (wa), も (mo), dan の (no)','text_grammar','Pada bab pertama ini, kita mempelajari struktur dasar kalimat bahasa Jepang.\n\n■ 1. Kata Benda 1 + は + Kata Benda 2 + です\nPartikel は (dibaca \'wa\') berfungsi sebagai penanda topik atau subjek kalimat.\nContoh: わたしは 田中(たなか)です (Saya adalah Tanaka).\n\n■ 2. Bentuk Negatif: ~じゃありません / ではありません\nContoh: サントスさんは 学生(がくせい)じゃありません (Sdr. Santos bukan mahasiswa).\n\n■ 3. Kalimat Tanya: ~ですか\nPartikel か di akhir kalimat berfungsi menggantikan tanda tanya (?).\nContoh: あなたは 実習生(じっしゅうせい)ですか (Apakah Anda peserta magang?).',NULL,NULL,NULL,NULL,45,1,1,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(3,3,'Tata Bahasa Bab 2: Kata Tunjuk Kore, Sore, Are','text_grammar','Kata tunjuk benda dibagi berdasarkan jarak pembicara dan lawan bicara:\n- これ (Kore) = Ini (dekat pembicara)\n- それ (Sore) = Itu (dekat lawan bicara)\n- あれ (Are) = Itu (jauh dari keduanya)\n- どれ (Dore) = Yang mana?\n\nPerbedaan これ dan この:\n- これ langsung diikuti partikel: これは 本(ほん)です。\n- この harus menempel pada kata benda: この本は わたしのです。',NULL,NULL,NULL,NULL,45,1,1,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(4,4,'Tata Bahasa Bab 3: Menanyakan Lokasi dan Fasilitas','text_grammar','■ Menunjukkan Tempat:\n- ここ (Koko) = Di sini\n- そこ (Soko) = Di situ\n- あそこ (Asoko) = Di sana\n- どこ (Doko) = Di mana?\n\n■ Bentuk Sopan Arah / Tempat:\n- こちら (Kochira), そちら (Sochira), あちら (Achira), どちら (Dochira)\n\nContoh: お手洗い(おてあらい)は どこですか (Toilet ada di mana?).',NULL,NULL,NULL,NULL,45,1,1,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(5,5,'Tata Bahasa Bab 4: Jam, Menit, dan Kata Kerja Waktu Lampau','text_grammar','■ Menyatakan Waktu:\n- Jam: [Angka] + 時 (じ / ji)\n- Menit: [Angka] + 分 (ふん / ぷん / fun/pun)\n- Setengah jam: 半 (はん / han)\n\n■ Konjugasi Kata Kerja Sopan (Bentuk Masu):\n- Positif Sekarang/Masa Depan: 起(お)きます (Bangun)\n- Negatif Sekarang/Masa Depan: 起きません (Tidak bangun)\n- Positif Lampau: 起きました (Tadi sudah bangun)\n- Negatif Lampau: 起きませんでした (Tadi tidak bangun)\n\nContoh: 毎朝(まいあさ) 6時(ろくじ)に 起きます (Setiap pagi bangun jam 6).',NULL,NULL,NULL,NULL,50,1,1,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(6,6,'Tata Bahasa Bab 5: Partikel Perpindahan へ (e) dan Alat で (de)','text_grammar','■ Partikel Perpindahan へ (dibaca \'e\'):\nMenunjukkan arah tujuan perpindahan.\nContoh: 来週(らいしゅう) 日本(にほん)へ 行(い)きます (Minggu depan pergi ke Jepang).\n\n■ Partikel Sarana / Transportasi で (de):\nContoh: 新幹線(しんかんせん)で 東京(とうきょう)へ 行きます (Pergi ke Tokyo naik Shinkansen).\n*Catatan: Jalan kaki = 歩(ある)いて (tanpa partikel で).\n\n■ Partikel Teman Bersama と (to):\nContoh: 友達(ともだち)と 買い物(かいもの)へ 行きます (Pergi berbelanja bersama teman).',NULL,NULL,NULL,NULL,50,1,1,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(7,7,'Tata Bahasa Bab 6: Partikel Objek を (o) & Tempat Aksi で (de)','text_grammar','■ Partikel Objek を (dibaca \'o\'):\nMenghubungkan kata kerja dengan objek sasarannya.\nContoh: パンを 食(た)べます (Makan roti), 水(みず)を 飲(の)みます (Minum air).\n\n■ Partikel Tempat Aktivitas で (de):\nMenunjukkan tempat di mana sebuah aktivitas dilakukan.\nContoh: レストランで ご飯(はん)を 食べます (Makan di restoran).\n\n■ Pola Ajakan:\n- ~ませんか (Maukah Anda...? - lebih sopan)\n  Contoh: 一緒(いっしょ)に お茶(ちゃ)を 飲みませんか。\n- ~ましょう (Mari kita...! - langsung)\n  Contoh: ちょっと 休(やす)みましょう (Mari istirahat sebentar!).',NULL,NULL,NULL,NULL,50,1,1,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(8,8,'Tata Bahasa Bab 7: Alat Aksi & Hubungan Memberi-Menerima','text_grammar','■ 1. Alat / Bahasa dengan で:\n- はしで 食べます (Makan menggunakan sumpit).\n- 日本語(にほんご)で レポートを 書きます (Menulis laporan dalam bahasa Jepang).\n\n■ 2. Memberi (あげる) dan Menerima (もらう):\n- [Pemberi] は [Penerima] に [Benda] を あげます。\n  Contoh: わたしは 田中さんに 花(はな)を あげました。\n- [Penerima] は [Pemberi] に/から [Benda] を もらいます。\n  Contoh: わたしは 先生に 本を もらいました。\n\n■ 3. Sudah (もう) vs Belum (まだ):\n- もう 昼(ひる)ご飯を 食べましたか。→ はい、もう 食べました / いいえ、まだです。',NULL,NULL,NULL,NULL,50,1,1,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(9,9,'Tata Bahasa Bab 8: Perubahan Bentuk Kata Sifat I & Na','text_grammar','Kata sifat dalam bahasa Jepang terbagi menjadi 2 kelompok besar:\n\n■ 1. Kata Sifat-I (Berakhiran huruf い):\n- Positif: 高(たか)いです (Mahal)\n- Negatif: 高くないです (Tidak mahal) → い diganti くない\n- Menerangkan Benda: 高い時計 (Jam yang mahal)\n\n■ 2. Kata Sifat-Na (Harus ditambah な saat menerangkan benda):\n- Positif: 親切(しんせつ)です (Ramah)\n- Negatif: 親切じゃありません (Tidak ramah)\n- Menerangkan Benda: 親切な人 (Orang yang ramah)\n\n■ Pengecualian Penting: いい (Bagus) → negatifnya: よくないです.',NULL,NULL,NULL,NULL,50,1,1,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(10,10,'Tata Bahasa Bab 9: Penggunaan Partikel が (ga) untuk Kemampuan & Kesukaan','text_grammar','Kata kerja / sifat berikut menggunakan partikel が (bukan を):\n\n■ 1. Kesukaan & Keinginan:\n- 好き(すき) / 嫌(きら)い: 日本料理(にほんりょうり)が 好きです (Suka masakan Jepang).\n\n■ 2. Kemahiran:\n- 上手(じょうず) / 下手(へた): 歌(うた)が 上手です (Pandai menyanyi).\n\n■ 3. Kepahaman & Kepemilikan:\n- わかります: 日本語が わかります (Mengerti bahasa Jepang).\n- あります: お金(かね)が あります (Ada / punya uang).\n\n■ 4. Menyatakan Alasan (から - Kara):\nContoh: 時間(じかん)が ありませんから、タクシーで 行きます (Karena tidak ada waktu, saya pergi naik taksi).',NULL,NULL,NULL,NULL,50,1,1,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(11,11,'Tata Bahasa Bab 10: Perbedaan あります vs います dan Posisi Ruang','text_grammar','■ 1. あります (Untuk Benda Mati & Tanaman):\nContoh: 机(つくえ)の 上(うえ)に 本が あります (Di atas meja ada buku).\n\n■ 2. います (Untuk Manusia & Hewan Bergerak):\nContoh: 庭(にわ)に 犬(いぬ)が います (Di halaman ada anjing).\nContoh: 事務所(じむしょ)に 先生が います (Di kantor ada guru).\n\n■ 3. Posisi Spasial (Lokasi):\n- うえ (Atas), した (Bawah), まえ (Depan), うしろ (Belakang), となり (Sebelah), なか (Dalam), そと (Luar), ちかく (Dekat).\n\nContoh: 机と ベッドの 間(あいだ)に 猫(ねこ)が います (Di antara meja dan kasur ada kucing).',NULL,NULL,NULL,NULL,50,1,1,'2026-10-21 06:18:06','2026-10-21 06:18:06');
/*!40000 ALTER TABLE `lessons` ENABLE KEYS */;
UNLOCK TABLES;

