INSERT INTO `question_categories` VALUES (8,'Konstruksi Kalimat Nominal & Partikel Topik (は・も・の)','IND-BUN-01','bunpou','N5','N5',2,'Mampu menyusun kalimat nominal dasar positif, negatif (~dewa arimasen), dan tanya (~desu ka) untuk menyatakan identitas diri, profesi, dan asal negara di lingkungan kerja.','2026-10-21 06:18:06','2026-10-21 06:18:06'),(9,'Penunjuk Objek & Lokasi Ruang (これ・それ・あれ・ここ・そこ)','IND-BUN-02','bunpou','N5','N5',3,'Mampu menanyakan dan menunjukkan letak barang, peralatan kerja, dan posisi fasilitas kerja kepada supervisor secara presisi.','2026-10-21 06:18:06','2026-10-21 06:18:06'),(10,'Waktu Kerja & Perpindahan (に・へ・から・まで・いきます)','IND-BUN-03','bunpou','N5','N5',5,'Mampu mengomunikasikan jadwal kerja harian, jam lembur, tanggal penugasan, serta moda transportasi perjalanan dinas.','2026-10-21 06:18:06','2026-10-21 06:18:06'),(11,'Objek Tindakan Kerja & Alat Mesin (を・で・します)','IND-BUN-04','bunpou','N5','N5',7,'Mampu menyatakan tindakan operasional kerja, penggunaan alat perkakas/mesin, dan serah-terima barang.','2026-10-21 06:18:06','2026-10-21 06:18:06'),(12,'Konjugasi Bentuk-Te & Instruksi Perintah (~てください・~てもいい)','IND-BUN-05','bunpou','N4','N4',NULL,'Mampu memahami dan merespons instruksi kerja, permohonan izin kepada atasan, serta aturan yang diperbolehkan di asrama/tempat kerja.','2026-10-21 06:18:06','2026-10-21 06:18:06'),(13,'Kepatuhan SOP & Larangan Kerja (~なければならない・~てはいけない)','IND-BUN-06','bunpou','N4','N4',NULL,'Mampu memahami rambu-rambu bahaya, kepatuhan keselamatan kerja, dan hal-hal yang dilarang keras (Kinshi) di tempat kerja Jepang.','2026-10-21 06:18:06','2026-10-21 06:18:06'),(14,'Kosakata Profesi, Relasi Kerja, & Perkenalan Diri','IND-GOI-01','moji_goi','N5','N5',2,'Menguasai kosakata jabatan, panggilan hierarki kerja (Kachou, Buchou, Senpai), dan salam resmi perkenalan kerja (Jikoshoukai).','2026-10-21 06:18:06','2026-10-21 06:18:06'),(15,'Kosakata Perlengkapan Kerja & Fasilitas Pabrik/Kantor','IND-GOI-02','moji_goi','N5','N5',4,'Menguasai kosakata nama-nama perkakas, APD (Kouzou/Anzen-gutsu), bagian gedung pabrik, dan denah operasional kerja.','2026-10-21 06:18:06','2026-10-21 06:18:06'),(16,'Kosakata Kata Kerja Operasional & Aktivitas Harian','IND-GOI-03','moji_goi','N5','N5',8,'Menguasai kata kerja aktivitas fisik kerja (tsukurimasu, hakobimasu, tsukaimasu, shuurishimasu, nomimasu, ikimasu).','2026-10-21 06:18:06','2026-10-21 06:18:06'),(17,'Kosakata Budaya Kerja 5S & Keselamatan (Anzen Dai-ichi)','IND-GOI-04','moji_goi','N4','N4',NULL,'Memahami istilah Seiri (Ringkas), Seiton (Rapi), Seisou (Resik), Seiketsu (Rawat), dan Shitsuke (Rajin) serta pemilahan sampah.','2026-10-21 06:18:06','2026-10-21 06:18:06'),(18,'Membaca Pengumuman Jadwal Shift & Memo Kerja','IND-DOK-01','dokkai','N4','N4',NULL,'Mampu memahami informasi kalender kerja, jam kerja bergilir (koutai-kinmu), dan memo pada papan informasi (Keijiban).','2026-10-21 06:18:06','2026-10-21 06:18:06'),(19,'Membaca Instruksi Formulir Permohonan & Catatan Sakit','IND-DOK-02','dokkai','N4','N4',NULL,'Mampu membaca formulir cuti (Yukyu), izin sakit (Byouki), dan formulir identitas diri standar perusahaan Jepang.','2026-10-21 06:18:06','2026-10-21 06:18:06'),(20,'Menyimak Sapaan & Instruksi Spontan Mandor/Supervisor','IND-CHOU-01','choukai','N4','N4',NULL,'Mampu menangkap maksud instruksi lisan cepat (chotto matte, kore katadukete) dan sapaan kerja harian.','2026-10-21 06:18:06','2026-10-21 06:18:06'),(21,'Menyimak Informasi Angka, Jam, & Kuantitas Pesanan','IND-CHOU-02','choukai','N5','N5',NULL,'Mampu menyimak penyebutan jumlah barang, nomor kode pesanan, dan jam pertemuan lisan secara akurat.','2026-10-21 06:18:06','2026-10-21 06:18:06');
