--
-- Table structure for table `questions`
--

DROP TABLE IF EXISTS `questions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `questions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_by` bigint unsigned DEFAULT NULL,
  `question_category_id` bigint unsigned DEFAULT NULL,
  `chapter_id` bigint unsigned DEFAULT NULL,
  `level` enum('N5','N4','N3','JFT_A2') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'N4',
  `level_code` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `section_type` enum('moji_goi','bunpou','dokkai','choukai') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'moji_goi',
  `instruction` text COLLATE utf8mb4_unicode_ci,
  `question_text` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `reading_passage` longtext COLLATE utf8mb4_unicode_ci,
  `image_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `audio_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `audio_play_limit` int NOT NULL DEFAULT '1',
  `explanation` longtext COLLATE utf8mb4_unicode_ci,
  `score_points` decimal(5,2) NOT NULL DEFAULT '1.00',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `questions_created_by_foreign` (`created_by`),
  KEY `questions_question_category_id_foreign` (`question_category_id`),
  KEY `questions_chapter_id_foreign` (`chapter_id`),
  KEY `q_sec_cat_idx` (`section_type`,`question_category_id`),
  KEY `q_level_idx` (`level`),
  CONSTRAINT `questions_chapter_id_foreign` FOREIGN KEY (`chapter_id`) REFERENCES `chapters` (`id`) ON DELETE SET NULL,
  CONSTRAINT `questions_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `questions_question_category_id_foreign` FOREIGN KEY (`question_category_id`) REFERENCES `question_categories` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=24 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `questions`
--

LOCK TABLES `questions` WRITE;
/*!40000 ALTER TABLE `questions` DISABLE KEYS */;
INSERT INTO `questions` VALUES (1,2,15,NULL,'N4','N4','moji_goi','＿＿＿の ことばは どう よみますか。１・２・３・４から いちばん いい ものを ひとつ えらんで ください。','きのう、あたらしい <ruby>病院<rt>＿＿＿</rt></ruby>へ いきました。',NULL,NULL,NULL,1,'Kata 「病院」 dibaca 「びょういん (byouin)」 yang berarti rumah sakit. Huruf 「病」 dibaca びょう (panjang) dan 「院」 dibaca いん.',2.00,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(2,2,10,NULL,'N4','N4','bunpou','（　　）に なにを 入れますか。A・B・C・Dから いちばん いい ものを ひとつ えらんで ください。','あしたは <ruby>試験<rt>しけん</rt></ruby>が あるので、きょうは 早く <ruby>帰<rt>かえ</rt></ruby>って ＿＿＿＿＿ んです。',NULL,NULL,NULL,1,'Sebelum pola penjelas alasan 「〜んです」, kata kerja menggunakan Bentuk Biasa (Futsuukei). Bentuk ingin (〜たい) futsuukei-nya adalah 〜たい. Jadi yang benar: 勉強したい (ingin belajar).',2.00,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(3,2,20,NULL,'N4','N4','choukai','まず 話を きいて ください。それから、ただしい こたえを えらんで ください。','男の 人と 女の 人が 話して います。男の 人は 何を 持って いきますか。',NULL,NULL,NULL,1,'Pada percakapan, perempuan meminta laki-laki membawa payung karena ramalan cuaca sore akan hujan.',3.00,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(4,2,15,NULL,'N4','N4','moji_goi','【問題 1】 下線の 言葉は どう 書きますか。１・２・３・４から いちばん いい ものを ひとつ えらんで ください。','きのう <ruby>病院<rt>びょういん</rt></ruby>へ 行って、<ruby>薬<rt>くすり</rt></ruby>を <u>のみました</u>。',NULL,NULL,NULL,2,'「のみました」 adalah bentuk lampau dari kata kerja 飲みます (minum). Kanji yang benar adalah 飲みました.',9.00,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(5,2,14,NULL,'N4','N4','moji_goi','【問題 2】 漢字の 読み方を １・２・３・４から えらんで ください。','来週から 日本の 工場で <u>研修</u>が 始まります。',NULL,NULL,NULL,2,'研修 dibaca けんしゅう (kenshuu) yang berarti pelatihan/training magang di Jepang.',9.00,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(6,2,12,NULL,'N4','N4','bunpou','【問題 3】 （ ）には 何を 入れますか。１・２・３・４から いちばん いい ものを ひとつ えらんで ください。','熱が ありますから、今日は 早く 帰って（ ）。',NULL,NULL,NULL,2,'Pola ~てもいいですか digunakan untuk meminta izin (\"Bolehkah saya pulang lebih cepat?\").',9.00,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(7,2,10,NULL,'N4','N4','bunpou','【問題 4】 （ ）に 入る 正しい 助詞を えらんで ください。','わたしは 日本（ ）車や 機械の 技術を 勉強したいです。',NULL,NULL,NULL,2,'Partikel で menunjukkan tempat terjadinya aktivitas belajar teknik di Jepang.',9.00,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(8,2,13,NULL,'N4','N4','bunpou','【問題 5】 正しい 文法表現を えらんで ください。','危ないですから、機械に 手を（ ）。',NULL,NULL,NULL,2,'Pola ~てはいけません menyatakan larangan keras (\"Dilarang menyentuh mesin\"). Bentuk te dari 触ります adalah 触って.',9.00,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(9,2,16,NULL,'N4','N4','moji_goi','【問題 6】 （ ）に 入る 最も 適切な 言葉を えらんで ください。','毎朝 仕事が 始まる 前に、全員で（ ）を します。',NULL,NULL,NULL,2,'朝礼 (chourei) adalah apel pagi / briefing kerja yang wajib diadakan di perusahaan Jepang.',9.00,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(10,2,11,NULL,'N4','N4','bunpou','【問題 7】 文法形式の 選択','パスポートを（ ）ことが ありますか。',NULL,NULL,NULL,2,'Pola ~た ことが あります menyatakan pengalaman di masa lalu. Bentuk Ta dari 見せます adalah 見せた.',9.00,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(11,2,19,NULL,'N4','N4','dokkai','【問題 8】 メモを 読んで、質問に 答えて ください。','【メモ】<br>「山田さんへ：今日の ミーティングは １４時から ２階の 第１会議室で 行います。資料を ５部 コピーして 持ってきて ください。 佐藤より」<br><br><b>質問：山田さんは 何を しなければなりませんか。</b>',NULL,NULL,NULL,2,'Berdasarkan memo, Sato meminta Yamada memfotokopi dokumen sebanyak 5 rangkap dan membawanya ke rapat.',9.00,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(12,2,10,NULL,'N4','N4','bunpou','【問題 9】 条件形（〜たら）の 選択','日本へ（ ）、まず 市役所で 住民登録を します。',NULL,NULL,NULL,2,'Pola ~たら (pengandaian/sekuensial waktu): 日本へ 行ったら (Setelah tiba di Jepang...).',9.00,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(13,2,16,NULL,'N4','N4','moji_goi','【問題 10】 意味が いちばん 近い ものを えらんで ください。','彼は とても <u>まじめな</u> 人です。',NULL,NULL,NULL,2,'まじめ (rajin, sungguh-sungguh, tekun dalam bekerja).',9.00,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(14,2,20,NULL,'N4','N4','choukai','【聴解 問題 1】 音声を 聞いて、男の人が これから 何を するか えらんで ください。','<b>【音声会話】</b><br>女：田中さん、この 書類を ３階の 事務所へ 届けて くれませんか。<br>男：はい、分かりました。すぐ 持って いきます。<br><br><b>質問：男の人は これから 何を しますか。</b>',NULL,NULL,'/storage/cbt/audios/choukai_1.wav',2,'Pria menyetujui permintaan wanita untuk mengantarkan dokumen ke kantor lantai 3.',9.00,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(15,2,21,NULL,'N4','N4','choukai','【聴解 問題 2】 音声を 聞いて、２人が 何時に 会うか えらんで ください。','<b>【音声会話】</b><br>女：明日の 集合時間は 何時ですか。<br>男：駅前に 朝 ８時半に 集まりましょう。<br>女：分かりました。８時３０分ですね。<br><br><b>質問：２人は 明日 何時に 集まりますか。</b>',NULL,NULL,'/storage/cbt/audios/choukai_2.wav',2,'Percakapan memastikan waktu kumpul adalah pukul 08:30 pagi (８時半).',9.00,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(16,2,20,NULL,'N4','N4','choukai','【聴解 問題 3】 音声を 聞いて、現場の 注意事項を えらんで ください。','<b>【工場内アナウンス】</b><br>「作業中は 必ず ヘルメットと 安全靴を 着用して ください。安全第一で 作業を 行いましょう。」<br><br><b>質問：作業員は何を 必ず 着用しなければなりませんか。</b>',NULL,NULL,'/storage/cbt/audios/choukai_3.wav',2,'Instruksi keselamatan mewajibkan pemakaian helm (ヘルメット) dan sepatu keselamatan (安全靴).',9.00,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(17,2,20,NULL,'N4','N4','choukai','【聴解 問題 4】 音声を 聞いて、正しい 交通手段を えらんで ください。','<b>【音声会話】</b><br>男：会社まで どうやって 来ますか。<br>女：家から 駅まで 自転車で 行って、そこから 電車で ２０分です。<br><br><b>質問：女の人は 会社まで 何で 行きますか。</b>',NULL,NULL,'/storage/cbt/audios/choukai_4.wav',2,'Wanita naik sepeda ke stasiun lalu naik kereta ke kantor.',9.00,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(18,2,20,NULL,'N4','N4','choukai','【聴解 問題 5】 音声を 聞いて、病気の 症状を えらんで ください。','<b>【病院での会話】</b><br>医者：どうしましたか。<br>患者：昨日の 夜から 頭が 痛くて、熱も ３８度 あります。<br><br><b>質問：患者の 症状は どれですか。</b>',NULL,NULL,'/storage/cbt/audios/choukai_5.wav',2,'Gejala pasien: sakit kepala (頭が痛い) dan demam 38 derajat (熱がある).',9.00,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(19,2,15,NULL,'N4','N4','moji_goi','【画像問題 1】 下の 看板の 画像を 見て、質問に 答えて ください。','<b>質問：この 工場の 看板には 何と 書いて ありますか。</b>',NULL,'/storage/cbt/images/sign_safety.svg',NULL,2,'Tulisan kanji pada rambu keselamatan hijau adalah 安全第一 (Anzen Daiichi - Utamakan Keselamatan).',9.00,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(20,2,19,NULL,'N4','N4','dokkai','【画像問題 2】 駅の 案内図を 見て、正しい 説明を えらんで ください。','<b>質問：青い 看板の 出口は どちらですか。</b>',NULL,'/storage/cbt/images/station_map.svg',NULL,2,'Berdasarkan denah stasiun, pintu keluar biru di sebelah kiri bertuliskan 北口 (Kita-guchi / Pintu Utara).',9.00,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(21,2,17,NULL,'N4','N4','moji_goi','【画像問題 3】 ゴミ箱の イラストを 見て、ペットボトルは どこに 捨てますか。','<b>質問：空の ペットボトル（Plastik Botol）は どの ゴミ箱に 捨てますか。</b>',NULL,'/storage/cbt/images/trash_sort.svg',NULL,2,'Botol plastik dan kaleng termasuk kategori 資源ゴミ (Sampah daur ulang) di kotak hijau.',9.00,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(22,2,19,NULL,'N4','N4','dokkai','【画像問題 4】 時計の イラストを 見て、質問に 答えて ください。','<b>質問：企業面接の 集合時間は 何時ですか。</b>',NULL,'/storage/cbt/images/clock_time.svg',NULL,2,'Jam dinding menunjukkan pukul 3 tepat sore hari (午後３時 / 15:00).',9.00,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(23,2,19,NULL,'N4','N4','dokkai','【画像問題 5】 介護現場の イラストを 見て、介助の 種類を えらんで ください。','<b>質問：イラストの 介護技術は 何の 介助ですか。</b>',NULL,'/storage/cbt/images/kaigo_transfer.svg',NULL,2,'Gambar mengilustrasikan teknik memindahkan pasien dari tempat tidur ke kursi roda (移乗介助 / Ijou Kaijo).',9.00,'2026-10-21 06:18:06','2026-10-21 06:18:06');
