INSERT INTO `site_settings` VALUES (1,'lpk_name','LPK Masayume','general','2026-10-21 06:18:06','2026-10-21 06:18:06'),(2,'lpk_tagline','Wujudkan Karir Impian ke Jepang Bersama LPK Masayume','general','2026-10-21 06:18:06','2026-10-21 06:18:06'),(3,'lpk_legal_info','Izin Resmi Kemenaker RI & Terakreditasi SO','general','2026-10-21 06:18:06','2026-10-21 06:18:06'),(4,'lpk_topbar_subtitle','Program Tokutei Ginou (SSW) & Magang Kerja Jepang','general','2026-10-21 06:18:06','2026-10-21 06:18:06'),(5,'lpk_hero_badge','LEMBAGA PELATIHAN KERJA JEPANG RESMI & TERPERCAYA','general','2026-10-21 06:18:06','2026-10-21 06:18:06'),(6,'lpk_hero_description','Membuka jalan karir profesional di Jepang melalui Program Tokutei Ginou (SSW) dan Magang Kerja. Didukung kurikulum terpadu JLPT N4, pelatih Sensei berpengalaman, dan sistem ujian CBT Digital mutakhir.','general','2026-10-21 06:18:06','2026-10-21 06:18:06'),(7,'reg_status_open','1','general','2026-10-21 06:18:06','2026-10-21 06:18:06'),(8,'reg_batch_title','Gelombang Angkatan Baru','general','2026-10-21 06:18:06','2026-10-21 06:18:06'),(9,'reg_card_subtitle','Target Kelulusan N4 & Penempatan Kerja','general','2026-10-21 06:18:06','2026-10-21 06:18:06'),(10,'reg_point_1_title','Target Kelulusan Terjamin','general','2026-10-21 06:18:06','2026-10-21 06:18:06'),(11,'reg_point_1_desc','Sertifikasi JLPT N4 & JFT-Basic A2 dalam waktu 4-6 bulan pembekalan.','general','2026-10-21 06:18:06','2026-10-21 06:18:06'),(12,'reg_point_2_title','Bebas Biaya Tak Terduga','general','2026-10-21 06:18:06','2026-10-21 06:18:06'),(13,'reg_point_2_desc','Transparan 100% rincian biaya pelatihan, paspor, MCU hingga tiket pesawat.','general','2026-10-21 06:18:06','2026-10-21 06:18:06'),(14,'reg_point_3_title','Penempatan Kerja Pasti','general','2026-10-21 06:18:06','2026-10-21 06:18:06'),(15,'reg_point_3_desc','Kerjasama resmi dengan puluhan Asosiasi Kumiai dan Perusahaan di seluruh Jepang.','general','2026-10-21 06:18:06','2026-10-21 06:18:06'),(16,'stat_passing_rate','98','general','2026-10-21 06:18:06','2026-10-21 06:18:06'),(17,'stat_passing_label','Tingkat Kelulusan Ujian N4','general','2026-10-21 06:18:06','2026-10-21 06:18:06'),(18,'stat_alumni_count','350+','general','2026-10-21 06:18:06','2026-10-21 06:18:06'),(19,'stat_alumni_label','Siswa Berangkat ke Jepang','general','2026-10-21 06:18:06','2026-10-21 06:18:06'),(20,'stat_partner_count','85+','general','2026-10-21 06:18:06','2026-10-21 06:18:06'),(21,'stat_partner_label','Mitra Perusahaan Jepang','general','2026-10-21 06:18:06','2026-10-21 06:18:06'),(22,'stat_legal_count','100%','general','2026-10-21 06:18:06','2026-10-21 06:18:06'),(23,'stat_legal_label','Izin Resmi Kemenaker','general','2026-10-21 06:18:06','2026-10-21 06:18:06'),(24,'about_title','Mencetak Tenaga Kerja Profesional Berkarakter & Berkualitas untuk Industri Jepang','general','2026-10-21 06:18:06','2026-10-21 06:18:06'),(25,'about_p1','LPK Masayume (株式会社 正夢) adalah Lembaga Pelatihan Kerja terkemuka yang berfokus pada pembekalan bahasa, budaya, kedisiplinan (Hensachi & Aisatsu), serta keterampilan teknis kerja di Jepang.','general','2026-10-21 06:18:06','2026-10-21 06:18:06'),(26,'about_p2','Kami menggabungkan metode pembelajaran tradisional yang intensif dengan platform digital modern (LMS & CBT Standar Jepang) sehingga seluruh siswa dipantau progres kemampuan bahasanya secara presisi dari nol hingga siap berangkat.','general','2026-10-21 06:18:06','2026-10-21 06:18:06'),(27,'about_feature_1_title','Sensei Native & N2','general','2026-10-21 06:18:06','2026-10-21 06:18:06'),(28,'about_feature_1_desc','Pengajar berpengalaman lulusan universitas Jepang & bersertifikat resmi.','general','2026-10-21 06:18:06','2026-10-21 06:18:06'),(29,'about_feature_2_title','Asrama & Fasilitas','general','2026-10-21 06:18:06','2026-10-21 06:18:06'),(30,'about_feature_2_desc','Lingkungan belajar kondusif dengan laboratorium bahasa & lab CBT mandiri.','general','2026-10-21 06:18:06','2026-10-21 06:18:06'),(31,'philosophy_title','Mimpi Nyata Menuju Masa Depan','general','2026-10-21 06:18:06','2026-10-21 06:18:06'),(32,'philosophy_desc','Dalam bahasa Jepang, 正夢 (Masayume) berarti \"Mimpi yang Menjadi Kenyataan\". Kami berkomitmen mendampingi setiap siswa agar mimpi bekerja dan sukses di Jepang terwujud secara aman, legal, dan bermartabat.','general','2026-10-21 06:18:06','2026-10-21 06:18:06'),(33,'contact_phone','0812-3456-7890','general','2026-10-21 06:18:06','2026-10-21 06:18:06'),(34,'contact_whatsapp','6281234567890','general','2026-10-21 06:18:06','2026-10-21 06:18:06'),(35,'contact_email','info@masayume-lpk.co.id','general','2026-10-21 06:18:06','2026-10-21 06:18:06'),(36,'contact_address','Gedung LPK Masayume, Jl. Pelatihan Karir Jepang No. 88, Jawa Barat, Indonesia','general','2026-10-21 06:18:06','2026-10-21 06:18:06'),(37,'contact_hours','Senin - Sabtu: 08.00 - 17.00 WIB','general','2026-10-21 06:18:06','2026-10-21 06:18:06'),(38,'contact_maps_url','https://maps.google.com','general','2026-10-21 06:18:06','2026-10-21 06:18:06'),(39,'social_instagram','https://instagram.com','general','2026-10-21 06:18:06','2026-10-21 06:18:06'),(40,'social_facebook','https://facebook.com','general','2026-10-21 06:18:06','2026-10-21 06:18:06'),(41,'social_tiktok','https://tiktok.com','general','2026-10-21 06:18:06','2026-10-21 06:18:06'),(42,'social_youtube','https://youtube.com','general','2026-10-21 06:18:06','2026-10-21 06:18:06'),(43,'footer_copyright','© 2026 LPK Masayume (正夢). Hak Cipta Dilindungi Undang-Undang.','general','2026-10-21 06:18:06','2026-10-21 06:18:06');
