INSERT INTO `topics` VALUES (1,'vocabulary','N5','Perkenalan Diri & Profesi','Kosakata sapaan awal, identitas, dan pekerjaan (自己紹介と職業)',1,1,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(2,'vocabulary','N5','Benda Sehari-hari & Sekolah','Benda-benda di sekitar kelas dan perlengkapan belajar (身の回りの物・学用品)',2,1,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(3,'vocabulary','N5','Ruangan & Fasilitas Bangunan','Nama ruangan, fasilitas sekolah/kantor dan lantai gedung (施設と部屋・建物)',3,1,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(4,'vocabulary','N5','Rutinitas & Jam Kerja','Aktivitas bangun, tidur, belajar, bekerja, dan istirahat (毎日の日課と時間)',4,1,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(5,'vocabulary','N5','Perpindahan & Transportasi','Kata kerja arah gerak dan sarana transportasi (移動動詞と乗り物)',5,1,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(6,'vocabulary','N5','Aktivitas Sehari-hari','Kata kerja makan, minum, membeli, melihat, mendengar, menulis (日常生活の動詞)',6,1,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(7,'vocabulary','N5','Transaksi & Pertukaran Benda','Kata kerja memberi, menerima, meminjam, meminjamkan, memotong, mengirim (やりもらいと授受動詞)',7,1,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(8,'vocabulary','N5','Sifat & Kondisi Lingkungan','Kata sifat untuk mendeskripsikan benda, sifat orang, dan suasana (形容詞・様子と性格)',8,1,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(9,'vocabulary','N5','Kemampuan, Minat & Waktu','Menyatakan kesukaan, kepandaian, pemahaman, dan waktu (能力・好み・時間)',9,1,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(10,'vocabulary','N5','Keberadaan & Posisi Ruang','Keberadaan makhluk hidup dan petunjuk letak / arah ruang (存在動詞と位置関係)',10,1,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(11,'kanji','N5','Hari & Kalender','Kanji hari dalam sepekan dan elemen alam dasar (曜日と自然元素)',1,1,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(12,'kanji','N5','Elemen & Bentang Alam','Kanji bentuk alam gunung, sungai, dan cuaca (自然地形・山川・天気)',2,1,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(13,'kanji','N5','Sosok Manusia & Keluarga','Kanji sosok manusia, anak, perempuan, dan keluarga (人と家族)',3,1,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(14,'kanji','N5','Pendidikan & Lembaga','Kanji belajar, sekolah, dan guru (学び・学校・先生)',4,1,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(15,'kanji','N5','Aktivitas & Aksi Dasar','Kanji kata kerja makan, minum, melihat, mendengar, pergi, datang (基本動作・生活)',5,1,'2026-10-21 06:18:06','2026-10-21 06:18:06'),(16,'kanji','N5','Ukuran & Posisi/Arah','Kanji ukuran besar kecil dan penunjuk arah posisi (大小・位置・方向)',6,1,'2026-10-21 06:18:06','2026-10-21 06:18:06');
