--
-- Table structure for table `vocabularies`
--

DROP TABLE IF EXISTS `vocabularies`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `vocabularies` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `level` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'N5',
  `category` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `chapter_id` bigint unsigned DEFAULT NULL,
  `kanji` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `hiragana` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `romaji` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `meaning_id` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `word_type` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'noun',
  `audio_file` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `image_file` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `example_sentence_jp` text COLLATE utf8mb4_unicode_ci,
  `example_sentence_id` text COLLATE utf8mb4_unicode_ci,
  `order_index` int NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `vocabularies_chapter_id_foreign` (`chapter_id`),
  KEY `vocabularies_level_index` (`level`),
  KEY `vocabularies_category_index` (`category`),
  CONSTRAINT `vocabularies_chapter_id_foreign` FOREIGN KEY (`chapter_id`) REFERENCES `chapters` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=66 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

